<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Sorting Visualizer</title>
    <style>
        body { 
            background-color: #1a1a1a; 
            color: white; 
            font-family: 'Segoe UI', sans-serif; 
            display: flex; 
            flex-direction: column; 
            align-items: center; 
            height: 100vh; 
            margin: 0; 
            justify-content: space-between;
        }

        .controls { 
            padding-top: 20px; 
            text-align: center; 
            width: 100%;
            max-width: 650px;
        }

        button { 
            background-color: #4CAF50; 
            color: white; 
            border: none; 
            padding: 12px 24px; 
            margin: 0 8px; 
            font-size: 16px; 
            cursor: pointer; 
            border-radius: 4px;
            transition: background-color 0.2s, opacity 0.2s;
        }

        button:hover { background-color: #3e8e41; opacity: 0.9;}
        button:active { transform: translateY(1px); }

        .label { margin-bottom: 10px; font-size: 14px; color: #aaa; text-align: center; width: 100%; max-width: 650px;}

        #bars-container { 
            display: flex; 
            align-items: flex-end; 
            height: 350px; /* Fixed container */
            width: 90%;     /* Responsive-ish but fixed enough */
            max-width: 650px;
            border-bottom: 4px solid #4CAF50;
            background-color: #2c3e50;
            padding-bottom: 10px;
            justify-content: space-evenly; 
            gap: 8px; 
        }

        .bar {
            flex-grow: 0;
            width: 30px; /* Fixed width, height varies */
            background-color: #ecf0f1;
            border-radius: 5px 5px 0 0;
            transition: height 0.2s ease-in-out; 
            min-height: 4px; 
        }

        .bar.active { 
            background-color: #ff6b6b !important; /* Highlight during comparison/swap */
            box-shadow: 0 0 10px rgba(255, 107, 107, 0.8);
        }
    </style>
</head>
<body>

<div class="label">Sorting Visualizer (Bubble Sort)</div>

<div class="controls">
    <button id="shuffle">Shuffle Array</button>
    <button id="sort">Sort Ascending</button>
    <button id="reset">Reset</button>
</div>

<div id="bars-container"></div>

<script>
(function() {
    'use strict';

    const container = document.getElementById('bars-container');
    let currentArray = []; 

    // Sorter state management (for Bubble Sort)
    class BubbleSorter {
        constructor(arr) {
            this.arr = arr; 
            this.n = arr.length;
            this.i = 0;      // Outer loop index
            this.j = 0;      // Inner loop start index
            this.finished = false;
        }

        step() {
            if (this.i >= this.n - 1) return null; 

            while (true) {
                if (this.j < this.n - this.i - 1) {
                    let aIdx = this.j;
                    let bIdx = this.j + 1;

                    // Perform comparison/swapping immediately to update array state before yielding back.
                    // This ensures the DOM reflects current data after step() call.
                    if (this.arr[aIdx] > this.arr[bIdx]) {
                        [this.arr[aIdx], this.arr[bIdx]] = [this.arr[bIdx], this.arr[aIdx]];
                    }

                    // Advance index for next comparison in sequence.
                    this.j++; 

                    return { indices: [aIdx, bIdx] };
                } else {
                    // Finish current i-loop, move to next outer iteration or finish.
                    this.i++;
                    this.j = 0;
                    if (this.i >= this.n - 1) return null; 
                    continue; 
                }
            }
        }

        isSorted() {
             let sortedVal = true;
             for(let k=1; k<this.arr.length; k++) {
                 if(this.arr[k-1] > this.arr[k]) {
                     sortedVal = false; break; 
                 }
             }
             return sortedVal;
        }

    }

    let sorterInstance = null;

    window.viz = {
        array: () => [...currentArray], // Return copy to avoid direct mutation issues

        setArray: (arr) => {
            currentArray = arr.slice(); 
            sorterInstance = null;      // Stop any sorting in progress

            renderBars(currentArray);

            // Reset highlight classes on existing bars if present
            const bars = document.querySelectorAll('.bar');
            bars.forEach(b => b.classList.remove('active'));
        },

        sorted: () => {
             let isSortedVal = true;
             for(let k=1; k<currentArray.length; k++) {
                 if(currentArray[k-1] > currentArray[k]) {
                     isSortedVal = false; break; 
                 }
             }
             return isSortedVal;
        },

        sortStep: () => {
            // If array is already sorted, no need to continue sorting. Return true (fully sorted).
            if (window.viz.sorted()) return true;

            if (!sorterInstance) {
                sorterInstance = new BubbleSorter(currentArray);
                // No visual highlight needed on creation yet.
            }

            const res = sorterInstance.step();

            if (res === null || sorterInstance.finished) {
                sorterInstance.finished = true;
                return true; // Sorting complete
            }

            updateVisuals(res.indices, currentArray);
            return false; // Not finished yet.
        }
    };

    function renderBars(data) {
        container.innerHTML = '';

        if (data.length === 0) return;

        const maxVal = Math.max(...data);

        data.forEach(val => {
            const bar = document.createElement('div');
            bar.className = 'bar';

            let h = 0;
            if (maxVal > 0) h = (val / maxVal) * 100;

            // Ensure visible minimum height for very small values? 
            // Just standard percentage. If val=0, height=0%. That's okay visually but might be invisible.
            bar.style.height = `${h}%`;

            container.appendChild(bar);
        });
    }

    function updateVisuals(indices, data) {
        const bars = document.querySelectorAll('.bar');

        // Clear highlights from previous steps (unless we want persistent highlight)
        bars.forEach(b => b.classList.remove('active'));

        indices.forEach(idx => {
            if (bars[idx]) {
                bars[idx].classList.add('active');

                // Update height for all bars to reflect current state (since swaps change values)
                const max = Math.max(...data);
                bars.forEach((bar, i) => {
                    let h = 0;
                    if(max > 0) h = (data[i] / max) * 100;
                    bar.style.height = `${h}%`;
                });
            }
        });

        // Remove highlight after short delay for visual feedback of the comparison step.
        setTimeout(() => {
            const barsToClear = document.querySelectorAll('.bar');
            barsToClear.forEach(b => b.classList.remove('active'));
        }, 200); 
    }

    // Button Logic
    document.getElementById('shuffle').onclick = () => {
         // Create random array of numbers (e.g., length 15, values 10-90)
         const arr = [];
         for(let i=0; i<20; i++) arr.push(Math.floor(Math.random()*80)+10);
         window.viz.setArray(arr);
    };

    document.getElementById('sort').onclick = () => {
        // If already sorted, nothing.
        if(window.viz.sorted()) return;

        let done = false;
        const loop = async () => {
            while (!done) {
                await new Promise(r => setTimeout(r, 30)); 
                done = window.viz.sortStep();
            }
        };
        loop();
    };

    document.getElementById('reset').onclick = () => {
         sorterInstance = null;
         // Reset to a sorted state of small numbers for clarity or empty.
         currentArray = [10, 20, 30]; 
         renderBars(currentArray);
    };

})();
</script>

</body>
</html>
